// [S4] Three-portal family features — appointments calendar with interactive month grid,
// daily event badges, filtering, and booking management matching the Web Scheduling Calendar.
import 'package:family_veda/models/appointment.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';

String _dayKey(DateTime date) =>
    '${date.year}-${date.month.toString().padLeft(2, '0')}-${date.day.toString().padLeft(2, '0')}';

class AppointmentsScreen extends ConsumerStatefulWidget {
  const AppointmentsScreen({super.key});

  @override
  ConsumerState<AppointmentsScreen> createState() => _AppointmentsScreenState();
}

class _AppointmentsScreenState extends ConsumerState<AppointmentsScreen> {
  DateTime _currentMonth = DateTime(DateTime.now().year, DateTime.now().month, 1);
  String? _selectedDate;
  String _activeFilter = 'all'; // 'all', 'today', 'week'

  Future<void> _cancel(String id) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Cancel Appointment'),
        content: const Text('Are you sure you want to cancel this appointment?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: const Text('Keep'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.danger),
            child: const Text('Cancel Visit', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );

    if (confirmed != true || !mounted) return;

    try {
      await ref.read(familyPortalApiProvider).cancelAppointment(id);
      ref.invalidate(myAppointmentsProvider);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Appointment cancelled.'),
            backgroundColor: AppColors.success,
          ),
        );
      }
    } on Object {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not cancel the appointment. Try again.'),
            backgroundColor: AppColors.danger,
          ),
        );
      }
    }
  }

  void _handlePrevMonth() {
    setState(() {
      _currentMonth = DateTime(_currentMonth.year, _currentMonth.month - 1, 1);
    });
  }

  void _handleNextMonth() {
    setState(() {
      _currentMonth = DateTime(_currentMonth.year, _currentMonth.month + 1, 1);
    });
  }

  void _handleToday() {
    final now = DateTime.now();
    setState(() {
      _currentMonth = DateTime(now.year, now.month, 1);
      _selectedDate = _dayKey(now);
    });
  }

  @override
  Widget build(BuildContext context) {
    final appointmentsAsync = ref.watch(myAppointmentsProvider);
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Scaffold(
      backgroundColor: Colors.transparent,
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () => context.push('/appointments/book'),
        icon: const Icon(Icons.add_rounded, size: 20),
        label: const Text('Book', style: TextStyle(fontWeight: FontWeight.w700)),
        backgroundColor: const Color(0xFF146CFF),
        foregroundColor: Colors.white,
      ),
      body: SafeArea(
        child: appointmentsAsync.when(
          loading: () => const LoadingStateView(label: 'Loading appointments'),
          error: (_, _) => ErrorRetryView(
            onRetry: () => ref.invalidate(myAppointmentsProvider),
          ),
          data: (items) {
            final now = DateTime.now();
            final todayKey = _dayKey(now);

            // Group appointments by dayKey
            final appointmentsByDate = <String, List<Appointment>>{};
            for (final a in items) {
              final k = _dayKey(a.startsAt);
              appointmentsByDate.putIfAbsent(k, () => []).add(a);
            }

            // Month title & this month count
            final monthTitle = DateFormat('MMMM yyyy').format(_currentMonth);
            final monthPrefix =
                '${_currentMonth.year}-${_currentMonth.month.toString().padLeft(2, '0')}';
            final thisMonthCount =
                items.where((a) => _dayKey(a.startsAt).startsWith(monthPrefix)).length;

            // Filter visible appointments
            final weekEnd = _dayKey(now.add(const Duration(days: 7)));
            final visible = items.where((a) {
              final k = _dayKey(a.startsAt);
              if (_selectedDate != null) return k == _selectedDate;
              if (_activeFilter == 'today') return k == todayKey;
              if (_activeFilter == 'week') {
                return k.compareTo(todayKey) >= 0 && k.compareTo(weekEnd) <= 0;
              }
              return true;
            }).toList()
              ..sort((a, b) => a.startsAt.compareTo(b.startsAt));

            return RefreshIndicator(
              onRefresh: () async => ref.invalidate(myAppointmentsProvider),
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(
                  parent: BouncingScrollPhysics(),
                ),
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                children: [
                  // 1. Web-Aligned Royal Blue Hero Banner
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(20),
                    decoration: BoxDecoration(
                      gradient: const LinearGradient(
                        colors: [Color(0xFF0F52BA), Color(0xFF1976D2), Color(0xFF0288D1)],
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                      ),
                      borderRadius: BorderRadius.circular(18),
                      boxShadow: [
                        BoxShadow(
                          color: const Color(0xFF0F52BA).withValues(alpha: 0.35),
                          blurRadius: 16,
                          offset: const Offset(0, 6),
                        ),
                      ],
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.2),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: const Text(
                            'SCHEDULING',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w800,
                              letterSpacing: 1.1,
                              color: Colors.white,
                            ),
                          ),
                        ),
                        const SizedBox(height: 8),
                        const Text(
                          'Calendar',
                          style: TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.w800,
                            color: Colors.white,
                            letterSpacing: -0.3,
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          "Your appointments. Confirm, reschedule, complete or cancel them. Confirming opens the patient's records from 24 h before the visit to 24 h after.",
                          style: TextStyle(
                            fontSize: 13,
                            color: Colors.white.withValues(alpha: 0.9),
                            height: 1.35,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 16),

                  // 2. Interactive Month Calendar Board
                  _buildCalendarBoard(
                    isDark: isDark,
                    monthTitle: monthTitle,
                    thisMonthCount: thisMonthCount,
                    todayKey: todayKey,
                    appointmentsByDate: appointmentsByDate,
                  ),
                  const SizedBox(height: 16),

                  // 3. Filter Controls & Selected Date Indicator
                  _buildFilterBar(isDark),
                  const SizedBox(height: 12),

                  // 4. Appointments List Cards
                  if (visible.isEmpty)
                    Container(
                      padding: const EdgeInsets.all(24),
                      decoration: BoxDecoration(
                        color: isDark ? AppColors.surfaceDark : AppColors.surface,
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(
                          color: isDark ? AppColors.borderDark : AppColors.border,
                        ),
                      ),
                      child: Column(
                        children: [
                          Icon(
                            Icons.calendar_month_outlined,
                            size: 40,
                            color: isDark ? AppColors.mutedDark : AppColors.muted,
                          ),
                          const SizedBox(height: 10),
                          Text(
                            _selectedDate != null
                                ? 'No appointments on ${_formatSelectedDate(_selectedDate!)}'
                                : 'No appointments scheduled',
                            style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w700,
                              color: isDark ? Colors.white : const Color(0xFF0F172A),
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            'Book a visit with your family doctor to schedule consultations.',
                            style: TextStyle(
                              fontSize: 13,
                              color: isDark ? AppColors.mutedDark : AppColors.muted,
                            ),
                            textAlign: TextAlign.center,
                          ),
                          const SizedBox(height: 14),
                          ElevatedButton.icon(
                            onPressed: () => context.push('/appointments/book'),
                            icon: const Icon(Icons.calendar_month_outlined, size: 16),
                            label: const Text('Book appointment', style: TextStyle(fontWeight: FontWeight.w700)),
                            style: ElevatedButton.styleFrom(
                              backgroundColor: const Color(0xFF1D61E0),
                              foregroundColor: Colors.white,
                              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(8),
                              ),
                            ),
                          ),
                        ],
                      ),
                    )
                  else ...[
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          _selectedDate != null
                              ? 'APPOINTMENTS ON ${_formatSelectedDate(_selectedDate!).toUpperCase()} (${visible.length})'
                              : 'UPCOMING APPOINTMENTS (${visible.length})',
                          style: TextStyle(
                            fontSize: 11.5,
                            fontWeight: FontWeight.w800,
                            letterSpacing: 0.8,
                            color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    ...visible.map((item) => _buildAppointmentCard(item, isDark)),
                  ],
                  const SizedBox(height: 40),
                ],
              ),
            );
          },
        ),
      ),
    );
  }

  Widget _buildCalendarBoard({
    required bool isDark,
    required String monthTitle,
    required int thisMonthCount,
    required String todayKey,
    required Map<String, List<Appointment>> appointmentsByDate,
  }) {
    final year = _currentMonth.year;
    final month = _currentMonth.month;
    final firstDayWeekday = DateTime(year, month, 1).weekday % 7; // Sunday = 0
    final daysInMonth = DateTime(year, month + 1, 0).day;
    final daysInPrevMonth = DateTime(year, month, 0).day;

    final cells = <_CalendarCellData>[];

    // Previous month padding days
    for (var i = firstDayWeekday - 1; i >= 0; i--) {
      final d = DateTime(year, month - 1, daysInPrevMonth - i);
      cells.add(_CalendarCellData(
        date: d,
        dateKey: _dayKey(d),
        isCurrentMonth: false,
        dayNumber: daysInPrevMonth - i,
      ));
    }

    // Current month days
    for (var i = 1; i <= daysInMonth; i++) {
      final d = DateTime(year, month, i);
      cells.add(_CalendarCellData(
        date: d,
        dateKey: _dayKey(d),
        isCurrentMonth: true,
        dayNumber: i,
      ));
    }

    // Next month padding days to complete week rows
    final remaining = (7 - (cells.length % 7)) % 7;
    for (var i = 1; i <= remaining; i++) {
      final d = DateTime(year, month + 1, i);
      cells.add(_CalendarCellData(
        date: d,
        dateKey: _dayKey(d),
        isCurrentMonth: false,
        dayNumber: i,
      ));
    }

    return Container(
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF1E293B) : Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: isDark ? 0.3 : 0.04),
            blurRadius: 12,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        children: [
          // 1. Month Top Bar
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
            child: Row(
              children: [
                Expanded(
                  child: Wrap(
                    crossAxisAlignment: WrapCrossAlignment.center,
                    spacing: 8,
                    runSpacing: 4,
                    children: [
                      Text(
                        monthTitle,
                        style: TextStyle(
                          fontSize: 16.5,
                          fontWeight: FontWeight.w800,
                          color: isDark ? Colors.white : const Color(0xFF0F172A),
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: const Color(0xFFE0F2FE),
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Text(
                          '$thisMonthCount ${thisMonthCount == 1 ? 'appointment' : 'appointments'} this month',
                          style: const TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF0284C7),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    _buildNavButton(
                      label: '‹ Prev',
                      onTap: _handlePrevMonth,
                      isDark: isDark,
                    ),
                    const SizedBox(width: 4),
                    _buildNavButton(
                      label: 'Today',
                      onTap: _handleToday,
                      isDark: isDark,
                      isToday: true,
                    ),
                    const SizedBox(width: 4),
                    _buildNavButton(
                      label: 'Next ›',
                      onTap: _handleNextMonth,
                      isDark: isDark,
                    ),
                  ],
                ),
              ],
            ),
          ),
          const Divider(height: 1, thickness: 1),

          // 2. Weekday Header Row (SUN, MON, TUE, WED, THU, FRI, SAT)
          Container(
            color: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Row(
              children: const [
                'SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT',
              ].map((wd) => Expanded(
                child: Center(
                  child: Text(
                    wd,
                    style: TextStyle(
                      fontSize: 10.5,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 0.5,
                      color: Color(0xFF64748B),
                    ),
                  ),
                ),
              )).toList(),
            ),
          ),
          const Divider(height: 1, thickness: 1),

          // 3. 7-Column Calendar Day Grid
          GridView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            itemCount: cells.length,
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 7,
              childAspectRatio: 0.68,
            ),
            itemBuilder: (context, index) {
              final cell = cells[index];
              final isToday = cell.dateKey == todayKey;
              final isSelected = cell.dateKey == _selectedDate;
              final appts = appointmentsByDate[cell.dateKey] ?? [];

              return InkWell(
                onTap: () {
                  setState(() {
                    if (isSelected) {
                      _selectedDate = null;
                    } else {
                      _selectedDate = cell.dateKey;
                      if (!cell.isCurrentMonth) {
                        _currentMonth = DateTime(cell.date.year, cell.date.month, 1);
                      }
                    }
                  });
                },
                child: Container(
                  decoration: BoxDecoration(
                    color: isSelected
                        ? (isDark ? const Color(0xFF1E3A8A).withValues(alpha: 0.4) : const Color(0xFFEFF6FF))
                        : (cell.isCurrentMonth
                            ? Colors.transparent
                            : (isDark ? const Color(0xFF0F172A).withValues(alpha: 0.5) : const Color(0xFFF8FAFC))),
                    border: Border.all(
                      color: isSelected
                          ? const Color(0xFF2563EB)
                          : (isDark ? const Color(0xFF334155).withValues(alpha: 0.6) : const Color(0xFFE2E8F0)),
                      width: isSelected ? 1.5 : 0.5,
                    ),
                  ),
                  padding: const EdgeInsets.all(3),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      // Day Number Indicator
                      Align(
                        alignment: Alignment.topRight,
                        child: isToday
                            ? Container(
                                width: 22,
                                height: 22,
                                decoration: const BoxDecoration(
                                  color: Color(0xFF2563EB),
                                  shape: BoxShape.circle,
                                ),
                                alignment: Alignment.center,
                                child: Text(
                                  '${cell.dayNumber}',
                                  style: const TextStyle(
                                    fontSize: 11,
                                    fontWeight: FontWeight.w800,
                                    color: Colors.white,
                                  ),
                                ),
                              )
                            : Text(
                                '${cell.dayNumber}',
                                style: TextStyle(
                                  fontSize: 11.5,
                                  fontWeight: FontWeight.w700,
                                  color: cell.isCurrentMonth
                                      ? (isDark ? Colors.white70 : const Color(0xFF334155))
                                      : (isDark ? const Color(0xFF475569) : const Color(0xFF94A3B8)),
                                ),
                              ),
                      ),
                      const SizedBox(height: 2),

                      // Mini Appointment Badges
                      Expanded(
                        child: ListView(
                          physics: const NeverScrollableScrollPhysics(),
                          children: [
                            ...appts.take(2).map((a) {
                              final isConfirmed = a.status == AppointmentStatus.confirmed;
                              final timeStr = DateFormat('h:mm a').format(a.startsAt);
                              final bg = isConfirmed
                                  ? const Color(0xFFDBEAFE)
                                  : const Color(0xFFFEF3C7);
                              final textCol = isConfirmed
                                  ? const Color(0xFF1D4ED8)
                                  : const Color(0xFFB45309);
                              final barCol = isConfirmed
                                  ? const Color(0xFF2563EB)
                                  : const Color(0xFFD97706);

                              return Container(
                                margin: const EdgeInsets.only(bottom: 2),
                                padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 1.5),
                                decoration: BoxDecoration(
                                  color: bg,
                                  borderRadius: BorderRadius.circular(3),
                                  border: Border(
                                    left: BorderSide(color: barCol, width: 2.5),
                                  ),
                                ),
                                child: Text(
                                  '$timeStr ${a.memberDisplayName}',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    fontSize: 8.5,
                                    fontWeight: FontWeight.w700,
                                    color: textCol,
                                  ),
                                ),
                              );
                            }),
                            if (appts.length > 2)
                              Text(
                                '+${appts.length - 2} more',
                                style: TextStyle(
                                  fontSize: 8,
                                  fontWeight: FontWeight.w800,
                                  color: isDark ? const Color(0xFF93C5FD) : const Color(0xFF2563EB),
                                ),
                              ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        ],
      ),
    );
  }

  Widget _buildNavButton({
    required String label,
    required VoidCallback onTap,
    required bool isDark,
    bool isToday = false,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(6),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
        decoration: BoxDecoration(
          color: isToday
              ? (isDark ? const Color(0xFF2563EB).withValues(alpha: 0.25) : const Color(0xFFEFF6FF))
              : (isDark ? const Color(0xFF334155) : const Color(0xFFF1F5F9)),
          borderRadius: BorderRadius.circular(6),
          border: Border.all(
            color: isToday
                ? const Color(0xFF2563EB)
                : (isDark ? const Color(0xFF475569) : const Color(0xFFCBD5E1)),
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w700,
            color: isToday
                ? (isDark ? const Color(0xFF93C5FD) : const Color(0xFF1D4ED8))
                : (isDark ? Colors.white : const Color(0xFF334155)),
          ),
        ),
      ),
    );
  }

  Widget _buildFilterBar(bool isDark) {
    return Row(
      children: [
        if (_selectedDate != null) ...[
          Expanded(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
              decoration: BoxDecoration(
                color: const Color(0xFFEFF6FF),
                borderRadius: BorderRadius.circular(8),
                border: Border.all(color: const Color(0xFFBFDBFE)),
              ),
              child: Row(
                children: [
                  const Icon(Icons.event, size: 16, color: Color(0xFF2563EB)),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      _formatSelectedDate(_selectedDate!),
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF1D4ED8),
                      ),
                    ),
                  ),
                  InkWell(
                    onTap: () => setState(() => _selectedDate = null),
                    child: const Icon(Icons.close, size: 16, color: Color(0xFF1D4ED8)),
                  ),
                ],
              ),
            ),
          ),
        ] else ...[
          _buildFilterChip('all', 'All', isDark),
          const SizedBox(width: 8),
          _buildFilterChip('week', 'This Week', isDark),
          const SizedBox(width: 8),
          _buildFilterChip('today', 'Today', isDark),
        ],
      ],
    );
  }

  Widget _buildFilterChip(String key, String label, bool isDark) {
    final isSelected = _activeFilter == key;
    return ChoiceChip(
      label: Text(label),
      selected: isSelected,
      onSelected: (_) => setState(() => _activeFilter = key),
      selectedColor: const Color(0xFF1D61E0),
      labelStyle: TextStyle(
        fontSize: 12,
        fontWeight: FontWeight.w700,
        color: isSelected ? Colors.white : (isDark ? Colors.white70 : const Color(0xFF475569)),
      ),
      backgroundColor: isDark ? const Color(0xFF1E293B) : const Color(0xFFF1F5F9),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(8),
        side: BorderSide(
          color: isSelected
              ? const Color(0xFF1D61E0)
              : (isDark ? const Color(0xFF334155) : const Color(0xFFCBD5E1)),
        ),
      ),
    );
  }

  Widget _buildAppointmentCard(Appointment item, bool isDark) {
    final isConfirmed = item.status == AppointmentStatus.confirmed;
    final isRequested = item.status == AppointmentStatus.requested;
    final badgeBg = isConfirmed
        ? const Color(0xFFDCFCE7)
        : isRequested
            ? const Color(0xFFFEF3C7)
            : const Color(0xFFF1F5F9);
    final badgeFg = isConfirmed
        ? const Color(0xFF166534)
        : isRequested
            ? const Color(0xFF92400E)
            : const Color(0xFF475569);

    final dateFormatted = DateFormat('EEE, MMM d, yyyy · h:mm a').format(item.startsAt);

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: isDark ? AppColors.surfaceDark : AppColors.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: isDark ? AppColors.borderDark : AppColors.border,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: isDark ? 0.2 : 0.03),
            blurRadius: 8,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 38,
                height: 38,
                decoration: BoxDecoration(
                  color: const Color(0xFF1D61E0).withValues(alpha: 0.12),
                  shape: BoxShape.circle,
                ),
                child: const Icon(Icons.person, color: Color(0xFF1D61E0), size: 20),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      item.memberDisplayName,
                      style: const TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      dateFormatted,
                      style: TextStyle(
                        fontSize: 12.5,
                        color: isDark ? AppColors.mutedDark : AppColors.muted,
                      ),
                    ),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: badgeBg,
                  borderRadius: BorderRadius.circular(6),
                ),
                child: Text(
                  item.status.friendlyLabel,
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w700,
                    color: badgeFg,
                  ),
                ),
              ),
            ],
          ),
          if (item.reason.isNotEmpty) ...[
            const SizedBox(height: 10),
            Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Row(
                children: [
                  Icon(
                    Icons.notes_rounded,
                    size: 16,
                    color: isDark ? AppColors.mutedDark : AppColors.muted,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      item.reason,
                      style: TextStyle(
                        fontSize: 12.5,
                        color: isDark ? Colors.white70 : const Color(0xFF334155),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
          if (item.status.isCancellable) ...[
            const SizedBox(height: 12),
            Align(
              alignment: Alignment.centerRight,
              child: OutlinedButton.icon(
                onPressed: () => _cancel(item.id),
                icon: const Icon(Icons.cancel_outlined, size: 14),
                label: const Text('Cancel visit', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700)),
                style: OutlinedButton.styleFrom(
                  foregroundColor: AppColors.danger,
                  side: const BorderSide(color: AppColors.danger),
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(8),
                  ),
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }

  String _formatSelectedDate(String key) {
    try {
      final parts = key.split('-').map(NumberFormat().parse).toList();
      final d = DateTime(parts[0].toInt(), parts[1].toInt(), parts[2].toInt());
      return DateFormat('EEEE, MMM d, yyyy').format(d);
    } catch (_) {
      return key;
    }
  }
}

class _CalendarCellData {
  const _CalendarCellData({
    required this.date,
    required this.dateKey,
    required this.isCurrentMonth,
    required this.dayNumber,
  });

  final DateTime date;
  final String dateKey;
  final bool isCurrentMonth;
  final int dayNumber;
}
